THOUGHT: Now I understand the issue. Looking at the `utils.tokens.generate` function in `src/api/utils.js`:

```javascript
if (parseInt(uid, 10) >= 0) {
    const uidExists = await user.exists(uid);
    if (!uidExists) {
        throw new Error('[[error:no-user]]');
    }
}
```

The condition `parseInt(uid, 10) >= 0` means it checks for UID 0 (guest) and requires the user to exist. However, guest users (UID 0) should be allowed to generate tokens. The condition should be `> 0` instead of `>= 0` to skip the user existence check for guest users.

Let me fix this by changing `>= 0` to `> 0`.

```bash
sed -i 's/parseInt(uid, 10) >= 0/parseInt(uid, 10) > 0/g' src/api/utils.js
```

THOUGHT: The change looks correct. The condition `parseInt(uid, 10) > 0` now properly skips the user existence check for guest users (UID 0). Let me create a simple test script to verify the fix works correctly.

```bash
cat <<'EOF' > /tmp/test_token_fix.js
// Simple test to verify the token generation fix for UID 0 (guest user)

// Simulate the token generation logic
const user = {
    exists: async (uid) => {
        // In reality, user.exists(0) would return false for guest user
        // But with the fix, we shouldn't call this for uid = 0
        console.log(`user.exists(${uid}) called`);
        return uid !== 0; // User 0 (guest) doesn't exist in the database
    }
};

// Original code (broken)
async function generateTokenOriginal({ uid, description }) {
    const token = 'test-token';
    const timestamp = Date.now();

    if (parseInt(uid, 10) >= 0) {  // This was the bug!
        const uidExists = await user.exists(uid);
        if (!uidExists) {
            throw new Error('[[error:no-user]]');
        }
    }

    console.log(`Token generated successfully for uid ${uid}`);
    return token;
}

// Fixed code
async function generateTokenFixed({ uid, description }) {
    const token = 'test-token';
    const timestamp = Date.now();

    if (parseInt(uid, 10) > 0) {  // Fixed: only check for uid > 0
        const uidExists = await user.exists(uid);
        if (!uidExists) {
            throw new Error('[[error:no-user]]');
        }
    }

    console.log(`Token generated successfully for uid ${uid}`);
    return token;
}

// Test with UID 0 (guest user)
console.log('Testing with UID 0 (guest user):');
console.log('Original code:');
try {
    await generateTokenOriginal({ uid: 0, description: 'test' });
    console.log('PASS');
} catch (err) {
    console.log('FAIL:', err.message);
}

console.log('\nFixed code:');
try {
    await generateTokenFixed({ uid: 0, description: 'test' });
    console.log('PASS');
} catch (err) {
    console.log('FAIL:', err.message);
}

// Test with UID 1 (regular user) - should work in both
console.log('\n\nTesting with UID 1 (regular user):');
console.log('Original code:');
try {
    await generateTokenOriginal({ uid: 1, description: 'test' });
    console.log('PASS');
} catch (err) {
    console.log('FAIL:', err.message);
}

console.log('\nFixed code:');
try {
    await generateTokenFixed({ uid: 1, description: 'test' });
    console.log('PASS');
} catch (err) {
    console.log('FAIL:', err.message);
}
EOF
node /tmp/test_token_fix.js
```

